mapper.select:
SELECT c.* FROM doc_chunk c
INNER JOIN document d ON d.id = c.document_id
LEFT JOIN `user` u ON u.id = d.user_id
WHERE (d.user_id = #{userId} OR u.role = 'TEACHER')

    AND d.id = #{documentId}

  AND (
    MATCH(c.content) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE)
    OR c.content LIKE CONCAT('%', #{keyword}, '%')
  )
LIMIT #{limit}
